@@ -1 +1,2 @@
-// Thin JSON client for the inventory upstream.
+import { sleep as realSleep } from './util.mjs';
+
@@ -12,4 +13,28 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  let lastError;
+  const maxAttempts = 3;
+
+  for (let attempt = 0; attempt < maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        const error = new HttpError(res.status, url);
+        // Don't retry 4xx errors
+        if (res.status >= 400 && res.status < 500) throw error;
+        // For 5xx, save and retry
+        lastError = error;
+      } else {
+        return res.json();
+      }
+    } catch (err) {
+      // Network errors: save and retry
+      if (err instanceof HttpError) throw err; // 5xx saved above, will retry; 4xx throws immediately
+      lastError = err;
+    }
+    // Backoff before retry: 100ms, 200ms
+    if (attempt < maxAttempts - 1) {
+      await sleep(100 * (attempt + 1));
+    }
+  }
+
+  throw lastError;
